function catSvg(kind){const common='viewBox="0 0 220 130"'; if(kind==='cobot')return `<svg ${common}><rect x="0" y="0" width="220" height="130" rx="18" fill="#edf0f4"/><circle cx="108" cy="86" r="24" fill="#8fb4ff"/><rect x="98" y="34" width="22" height="60" rx="11" fill="#5f8cff" transform="rotate(-28 109 64)"/><circle cx="84" cy="35" r="17" fill="#8fb4ff"/><rect x="84" y="28" width="69" height="18" rx="9" fill="#5f8cff" transform="rotate(12 118 37)"/><circle cx="157" cy="47" r="13" fill="#8fb4ff"/></svg>`; if(kind==='welding')return `<svg ${common}><rect width="220" height="130" rx="18" fill="#edf0f4"/><rect x="55" y="89" width="80" height="24" rx="8" fill="#f0b51c"/><rect x="88" y="40" width="18" height="63" rx="9" fill="#f0b51c" transform="rotate(-25 97 72)"/><rect x="92" y="32" width="78" height="16" rx="8" fill="#f0b51c"/><path d="M171 42 L195 77" stroke="#202938" stroke-width="8"/><path d="M194 76 l7 7 m-7-7 l-8 10 m8-10 l2 13" stroke="#ff7a00" stroke-width="3"/></svg>`; if(kind==='painting')return `<svg ${common}><rect width="220" height="130" rx="18" fill="#edf0f4"/><rect x="54" y="88" width="72" height="25" rx="8" fill="#72a5ff"/><rect x="84" y="38" width="18" height="65" rx="9" fill="#72a5ff" transform="rotate(-26 93 70)"/><rect x="91" y="29" width="77" height="16" rx="8" fill="#72a5ff"/><path d="M168 36 L195 58" stroke="#202938" stroke-width="7"/><circle cx="200" cy="58" r="3" fill="#2848ff"/><circle cx="205" cy="66" r="3" fill="#2848ff"/><circle cx="198" cy="72" r="3" fill="#2848ff"/></svg>`; if(kind==='pallet')return `<svg ${common}><rect width="220" height="130" rx="18" fill="#edf0f4"/><rect x="31" y="91" width="72" height="15" rx="4" fill="#a87336"/><rect x="35" y="70" width="28" height="20" fill="#d49a55"/><rect x="65" y="70" width="28" height="20" fill="#c88943"/><rect x="121" y="88" width="65" height="25" rx="8" fill="#f0b51c"/><rect x="141" y="32" width="17" height="67" rx="8" fill="#f0b51c" transform="rotate(25 150 66)"/><rect x="86" y="26" width="67" height="15" rx="7" fill="#f0b51c"/></svg>`; if(kind==='scara')return `<svg ${common}><rect width="220" height="130" rx="18" fill="#edf0f4"/><rect x="104" y="35" width="26" height="76" rx="8" fill="#9aa6b2"/><rect x="54" y="36" width="68" height="16" rx="8" fill="#687789"/><rect x="48" y="34" width="14" height="14" rx="7" fill="#9aa6b2"/><rect x="122" y="55" width="60" height="14" rx="7" fill="#687789"/><rect x="174" y="58" width="8" height="43" rx="4" fill="#202938"/></svg>`; if(kind==='delta')return `<svg ${common}><rect width="220" height="130" rx="18" fill="#edf0f4"/><rect x="45" y="25" width="130" height="12" rx="6" fill="#707d8e"/><path d="M65 37 L99 89 M110 37 L110 89 M155 37 L121 89" stroke="#8491a3" stroke-width="6"/><circle cx="110" cy="94" r="13" fill="#202938"/></svg>`; if(kind==='heavy')return `<svg ${common}><rect width="220" height="130" rx="18" fill="#edf0f4"/><rect x="43" y="91" width="98" height="26" rx="8" fill="#e8aa12"/><circle cx="103" cy="82" r="27" fill="#f4bf2d"/><rect x="96" y="28" width="23" height="68" rx="11" fill="#e8aa12" transform="rotate(-18 108 62)"/><rect x="111" y="23" width="76" height="20" rx="10" fill="#e8aa12"/></svg>`; return `<svg ${common}><rect width="220" height="130" rx="18" fill="#edf0f4"/><rect x="60" y="91" width="82" height="24" rx="8" fill="#f0b51c"/><circle cx="102" cy="81" r="24" fill="#f6c83f"/><rect x="94" y="38" width="18" height="57" rx="9" fill="#f0b51c" transform="rotate(-25 103 67)"/><rect x="101" y="30" width="73" height="16" rx="8" fill="#f0b51c"/></svg>`}
function applyLang(lang){if(!T[lang])lang='en';document.documentElement.lang=lang;const t=T[lang];document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;el.textContent=t[k]??T.en[k]??el.textContent});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const k=el.dataset.i18nPlaceholder;el.placeholder=t[k]??T.en[k]??el.placeholder});document.querySelectorAll('[data-i18n-html]').forEach(el=>{const k=el.dataset.i18nHtml;el.innerHTML=t[k]??T.en[k]??el.innerHTML});localStorage.setItem('rqLangV14',lang);renderCategories();renderListings();renderMakers();renderCompanies()}
function route(id){document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));document.getElementById(id)?.classList.add('active');window.scrollTo(0,0)}
document.querySelectorAll('[data-route]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();route(el.dataset.route)}));
function renderCategories(){const lang=document.documentElement.lang||'ko';const html=categories.map(c=>`<article class="category-card" data-cat="${c.id}"><div class="category-visual">${catSvg(c.icon)}</div><div class="category-info"><h3>${c.names[lang]||c.names.en}</h3><p>${c.desc[lang]||c.desc.en}</p></div></article>`).join('');document.getElementById('categoryGrid').innerHTML=html;document.getElementById('homeCategoryStrip').innerHTML=categories.slice(0,4).map(c=>`<article class="category-card" data-cat="${c.id}"><div class="category-visual">${catSvg(c.icon)}</div><div class="category-info"><h3>${c.names[lang]||c.names.en}</h3><p>${c.desc[lang]||c.desc.en}</p></div></article>`).join('');document.querySelectorAll('.category-card').forEach(el=>el.addEventListener('click',()=>{document.getElementById('categoryFilter').value=el.dataset.cat;route('robots');renderListings()}));const sf=document.getElementById('categoryFilter');if(sf.options.length<=1)categories.forEach(c=>{const o=document.createElement('option');o.value=c.id;o.textContent=c.names[lang]||c.names.en;sf.appendChild(o)});else [...sf.options].slice(1).forEach((o,i)=>o.textContent=categories[i].names[lang]||categories[i].names.en)}
function yen(n){return n?new Intl.NumberFormat('ja-JP',{style:'currency',currency:'JPY',maximumFractionDigits:0}).format(n):tr('getOffers')}
function listingCard(r){const bid=r.sale==='bid';return `<article class="listing-card"><div class="listing-photo"><span class="country-badge">${r.country}</span><span class="listing-badge">${bid?tr('bidding'):tr('fixedPrice')}</span><div class="mini-robot"></div></div><div class="listing-body"><h3>${r.brand} ${r.model}</h3><div class="listing-meta">${r.year} · ${r.payload} · ${r.location}</div><div class="listing-price"><strong>${yen(r.price)}</strong><span class="verified">${r.verified?'✓ VERIFIED':tr('directory')}</span></div><div class="listing-actions"><button class="card-btn" onclick="openAuth('inquiry','${r.brand} ${r.model}')">${tr('askSeller')}</button><button class="card-btn main" onclick="openAuth('${bid?'bid':'buy'}','${r.brand} ${r.model}')">${bid?tr('placeBid'):tr('buyContact')}</button></div></div></article>`}
function renderListings(){const q=(document.getElementById('marketSearch')?.value||'').toLowerCase();const cat=document.getElementById('categoryFilter')?.value||'';const country=document.getElementById('countryFilter')?.value||'';const sale=document.getElementById('saleFilter')?.value||'';let all=[...listings,...JSON.parse(localStorage.getItem('rqListings')||'[]')];let filtered=all.filter(r=>(!q||`${r.brand} ${r.model} ${r.location}`.toLowerCase().includes(q))&&(!cat||r.cat===cat)&&(!country||r.country===country)&&(!sale||r.sale===sale));document.getElementById('marketListings').innerHTML=filtered.map(listingCard).join('')||'<p>No results.</p>';document.getElementById('homeListings').innerHTML=all.slice(0,3).map(listingCard).join('')}
['marketSearch','categoryFilter','countryFilter','saleFilter'].forEach(id=>document.getElementById(id)?.addEventListener('input',renderListings));
let makerTab='robot';function renderMakers(){const list=makers[makerTab];document.getElementById('makerGrid').innerHTML=list.map(m=>`<article class="maker-card"><div class="maker-mark">${m[0]}</div><h3>${m[0]}</h3><p>${m[1]}</p><button class="card-btn" onclick="showMaker('${m[0]}')">${tr('explore')}</button></article>`).join('')}
document.querySelectorAll('[data-maker-tab]').forEach(b=>b.addEventListener('click',()=>{makerTab=b.dataset.makerTab;document.querySelectorAll('[data-maker-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderMakers()}));
window.showMaker=function(name){const region=name==='OnRobot'?`<div class="tag-row"><span>Japan</span><span>Korea</span><span>Europe</span><span>North America</span></div><p>${tr('regionalSupportBody')}</p>`:'';openModal(`<div class="kicker">MANUFACTURER</div><h2>${name}</h2><p>${tr('makerModalBody')}</p>${region}<div class="modal-actions"><button class="secondary" onclick="closeModal()">${tr('close')}</button><button class="primary" onclick="openAuth('maker','${name}')">${tr('contactQuote')}</button></div>`)}
function renderCompanies(){const q=(document.getElementById('companySearch')?.value||'').toLowerCase();const type=document.getElementById('companyTypeFilter')?.value||'';const list=companies.filter(c=>(!q||`${c.name} ${c.type} ${c.region} ${c.skills.join(' ')}`.toLowerCase().includes(q))&&(!type||c.type===type));document.getElementById('companyGrid').innerHTML=list.map(c=>`<article class="company-card"><div class="company-top"><div class="company-logo">${c.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><span class="status ${c.status.includes('Pilot')?'verified':''}">${c.status}</span></div><h3>${c.name}</h3><div class="company-type">${c.type} · ${c.region}</div><div class="tag-row">${c.skills.map(s=>`<span>${s}</span>`).join('')}</div><div class="company-contact"><button class="card-btn main" onclick="openAuth('company','${c.name}')">${tr('contact')}</button><button class="card-btn" onclick="claimCompany('${c.name}')">${tr('claimProfile')}</button></div></article>`).join('')}
['companySearch','companyTypeFilter'].forEach(id=>document.getElementById(id)?.addEventListener('input',renderCompanies));
function openModal(html){document.getElementById('modal').innerHTML=html;document.getElementById('modalBackdrop').classList.remove('hidden')}window.closeModal=()=>document.getElementById('modalBackdrop').classList.add('hidden');document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
window.openAuth=function(type,target){openModal(`<div class="kicker">ROBOQUO ACCESS</div><h2>${tr('authTitle')}</h2><p>${tr('authBody')}</p><label>${tr('email')}<input id="authEmail" type="email" placeholder="name@company.com"></label><div class="modal-actions"><button class="secondary" onclick="closeModal()">${tr('cancel')}</button><button class="primary" onclick="completeAuth('${type}','${target.replaceAll("'","\\'")}')">${tr('continue')}</button></div>`)}
window.completeAuth=function(type,target){const email=document.getElementById('authEmail').value.trim();if(!email||!email.includes('@')){toast(tr('emailRequired'));return}localStorage.setItem('rqUserEmail',email);if(type==='bid')openBid(target);else{closeModal();toast(`${target}: ${tr('requestStarted')}`)}}
function openBid(target){openModal(`<div class="kicker">BIDDING</div><h2>${target}</h2><p>${tr('bidBody')}</p><label>${tr('offerPrice')}<input id="bidPrice" type="number" value="1200000"></label><label>${tr('message')}<textarea id="bidMsg" rows="3"></textarea></label><div class="modal-actions"><button class="secondary" onclick="closeModal()">${tr('cancel')}</button><button class="primary" onclick="submitBid('${target.replaceAll("'","\\'")}')">${tr('submitBid')}</button></div>`)}
window.submitBid=function(target){const bids=JSON.parse(localStorage.getItem('rqBids')||'[]');bids.push({target,price:+document.getElementById('bidPrice').value,email:localStorage.getItem('rqUserEmail'),date:new Date().toISOString()});localStorage.setItem('rqBids',JSON.stringify(bids));closeModal();toast(tr('bidSubmitted'))}
function sellFlow(){const lang=document.documentElement.lang;openModal(`<div class="kicker">SELL WITH ROBOQUO</div><h2>${tr('sellModalTitle')}</h2><p>${tr('sellModalBody')}</p><div class="dropzone">📷<br><strong>${tr('photoGuide')}</strong><br><input type="file" multiple accept="image/*,video/*"></div><label>${tr('company')}<input id="sellCompany" placeholder="ABC Automation"></label><div class="form-grid"><label>${tr('maker')}<input id="sellBrand" value="FANUC"></label><label>${tr('model')}<input id="sellModel" value="M-20iA/20M"></label><label>${tr('year')}<input id="sellYear" type="number" value="2020"></label><label>${tr('country')}<select id="sellCountry"><option>Japan</option><option>Korea</option><option>Germany</option><option>USA</option></select></label></div><label>${tr('category')}<select id="sellCat">${categories.map(c=>`<option value="${c.id}">${c.names[lang]||c.names.en}</option>`).join('')}</select></label><label>${tr('saleMethod')}<select id="sellSale"><option value="fixed">${tr('fixedPrice')}</option><option value="bid">${tr('getBids')}</option></select></label><label>${tr('priceJpy')}<input id="sellPrice" type="number" value="1200000"></label><div class="modal-actions"><button class="secondary" onclick="closeModal()">${tr('cancel')}</button><button class="primary" onclick="saveListing()">${tr('publishDemo')}</button></div>`)}
document.querySelectorAll('[data-action="sell"]').forEach(b=>b.addEventListener('click',sellFlow));
window.saveListing=function(){const arr=JSON.parse(localStorage.getItem('rqListings')||'[]');arr.unshift({id:Date.now(),brand:document.getElementById('sellBrand').value,model:document.getElementById('sellModel').value,year:+document.getElementById('sellYear').value,payload:'—',country:document.getElementById('sellCountry').value,location:document.getElementById('sellCountry').value,price:+document.getElementById('sellPrice').value,sale:document.getElementById('sellSale').value,cat:document.getElementById('sellCat').value,verified:false});localStorage.setItem('rqListings',JSON.stringify(arr));closeModal();renderListings();route('robots');toast(tr('listingPublished'))}
window.claimCompany=function(name){openAuth('claim',name)}
document.getElementById('registerCompanyBtn').addEventListener('click',()=>{openModal(`<div class="kicker">COMPANY DIRECTORY</div><h2>${tr('registerCompanyTitle')}</h2><p>${tr('registerCompanyBody')}</p><label>${tr('company')}<input></label><label>${tr('businessEmail')}<input type="email"></label><label>${tr('address')}<input></label><label>${tr('phone')}<input></label><label>${tr('supportedMakers')}<input placeholder="FANUC, Yaskawa, OnRobot"></label><div class="modal-actions"><button class="secondary" onclick="closeModal()">${tr('cancel')}</button><button class="primary" onclick="closeModal();toast(tr('companySaved'))">${tr('save')}</button></div>`)})
document.getElementById('projectForm').addEventListener('submit',e=>{e.preventDefault();openAuth('project','Project')});
document.getElementById('myRoboquoBtn').addEventListener('click',()=>{const email=localStorage.getItem('rqUserEmail');const bids=JSON.parse(localStorage.getItem('rqBids')||'[]');openModal(`<div class="kicker">MY ROBOQUO</div><h2>${email||tr('guest')}</h2><p>${email?tr('signedDemo'):tr('browseAccount')}</p><div class="tag-row"><span>${bids.length} ${tr('bidsLabel')}</span><span>${JSON.parse(localStorage.getItem('rqListings')||'[]').length} ${tr('demoListings')}</span></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">${tr('close')}</button></div>`)})
document.getElementById('searchBtn').addEventListener('click',()=>{document.getElementById('marketSearch').value=document.getElementById('globalSearch').value;route('robots');renderListings()});document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter')document.getElementById('searchBtn').click()});
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1900)}
const storedLang=localStorage.getItem('rqLangV14');const saved=(storedLang&&T[storedLang])?storedLang:'en';document.getElementById('languageSelect').value=saved;document.getElementById('languageSelect').addEventListener('change',e=>applyLang(e.target.value));applyLang(saved);if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('service-worker.js').catch(()=>{}))}
